<?php
use NxMultiTool\Registry;
use NxMultiTool\AdminController;
use NxMultiTool\Content;
$filter = AdminController::contentFilter($_GET);
$categories = \app\Models\Category::all();
$exportQuery = $_GET; $exportQuery['tool'] = 'post_data'; $exportQuery['_csrf_token'] = \app\Core\Csrf::token();
?>
<section class="nxmt-panel"><form method="get" action="<?= e(Registry::url()) ?>"><input type="hidden" name="tool" value="post_data"><div class="nxmt-fields"><label>対象<select name="type"><option value="post" <?= $filter['type'] === 'post' ? 'selected' : '' ?>>投稿</option><option value="page" <?= $filter['type'] === 'page' ? 'selected' : '' ?>>固定ページ</option></select></label><label>タイトル検索<input name="q" value="<?= e($filter['q']) ?>"></label><label>公開状態<select name="status"><?php foreach (['' => 'すべて', 'published' => '公開', 'draft' => '下書き'] as $key => $label): ?><option value="<?= e($key) ?>" <?= $filter['status'] === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>カテゴリ<select name="category"><option value="0">すべて</option><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= $filter['category'] == $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label>並び替え<select name="sort"><?php foreach (['id' => 'ID', 'title' => 'タイトル', 'status' => '公開状態', 'slug' => 'スラッグ', 'created_at' => '作成日', 'updated_at' => '更新日'] as $key => $label): ?><option value="<?= e($key) ?>" <?= $filter['sort'] === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></label><label>順序<select name="order"><option value="DESC" <?= $filter['order'] === 'DESC' ? 'selected' : '' ?>>降順</option><option value="ASC" <?= $filter['order'] === 'ASC' ? 'selected' : '' ?>>昇順</option></select></label></div><button type="submit">絞り込む</button> <a class="button secondary" data-post-csv href="<?= e(Registry::endpoint('export') . '?' . http_build_query($exportQuery)) ?>">CSV出力</a></form><details><summary>表示・出力項目を選択</summary><div class="nxmt-inline"><?php foreach (Content::columns() as $index => $label): ?><label><input type="checkbox" data-post-column="<?= $index ?>" checked><?= e($label) ?></label><?php endforeach; ?></div></details><p class="nxmt-muted">閲覧数はアクセスログの保持期間・記録上限内の参考値です。説明文は個別SEO設定があればそれを参照し、それ以外は抜粋を表示します。</p></section>
<div class="nxmt-table-wrap"><table data-post-table><thead><tr><?php foreach (Content::columns() as $label): ?><th><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($data['metrics'] as $row): ?><tr><?php foreach ($row as $index => $cell): ?><td><?php if ($index === 3): ?><a href="<?= e(url('admin/' . ($data['type'] === 'post' ? 'posts' : 'pages') . '/edit/' . $row[0])) ?>"><?= e((string)$cell) ?></a><?php else: ?><?= e((string)$cell) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php AdminController::pagination('post_data', $page, $data['total']); ?>
